-- Dissect: Order Origin
cboe_bzxoptions_binaryorderentry_boe_v2_11_115.order_origin.dissect = function(buffer, offset, packet, parent)
  local length = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.order_origin.size
  local range = buffer(offset, length)

  -- parse last octet
  local last = buffer(offset + length - 1, 1):uint()

  -- read full string or up to first zero
  local value = ''
  if last == 0 then
    value = range:stringz()
  else
