  local display = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.order_origin.display(value, buffer, offset, packet, parent)

  parent:add(omi_cboe_bzxoptions_binaryorderentry_boe_v2_11_115.fields.order_origin, range, value, display)

  return offset + length, value
end

