-- Size: Send Time
cboe_bzxoptions_binaryorderentry_boe_v2_11_115.send_time.size = 8

-- Dissect: Send Time
cboe_bzxoptions_binaryorderentry_boe_v2_11_115.send_time.dissect = function(buffer, offset, packet, parent)
  local length = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.send_time.size
  local range = buffer(offset, length)
  local value = range:le_uint64()

  -- A field's absolute time base is fixed when it is declared, so the
  -- protocol declares one per base and the preference picks between them
  local field = omi_cboe_bzxoptions_binaryorderentry_boe_v2_11_115.fields.send_time
  if cboe_bzxoptions_binaryorderentry_boe_v2_11_115.absolute_time_base == 1 then field = omi_cboe_bzxoptions_binaryorderentry_boe_v2_11_115.fields.send_time_utc end

  local seconds = (value / UInt64(1000000000)):tonumber()
  local nanos = (value % UInt64(1000000000)):tonumber()
  parent:add(field, range, NSTime.new(seconds, nanos))

  return offset + length, value
end

