-- Read runtime size of: New Complex Order Message
cboe_bzxoptions_binaryorderentry_boe_v2_11_115.new_complex_order_message.size = function(buffer, offset)
  local index = offset

  -- Dependency element: Message Length
  local message_length = buffer(offset - 8, 2):le_uint()

  return message_length - 8
end

