end

-- Dissect Fields: New Complex Order Message
cboe_bzxoptions_binaryorderentry_boe_v2_11_115.new_complex_order_message.fields = function(buffer, offset, packet, parent, size_of_new_complex_order_message)
  local index = offset

  -- Cl Ord Id: Text
  index, cl_ord_id = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.cl_ord_id.dissect(buffer, index, packet, parent)

  -- Side: Alphanumeric
  index, side = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.side.dissect(buffer, index, packet, parent)

  -- Order Qty Binary 4: Binary
