-- Size of Order Allocations: not written, it needs Number Of New Order Cross Bitfields, New Order Cross Bitfield 2, New Order Cross Bitfield 4 passed down from New Order Cross Message

-- Display: Order Allocations
cboe_bzxoptions_binaryorderentry_boe_v2_11_115.order_allocations.display = function(packet, parent, length)
  return ""
end

-- Dissect Fields: Order Allocations
cboe_bzxoptions_binaryorderentry_boe_v2_11_115.order_allocations.fields = function(buffer, offset, packet, parent, order_allocations_index, number_of_new_order_cross_bitfields, new_order_cross_bitfield_2, new_order_cross_bitfield_4)
  local index = offset

  -- Implicit Order Allocations Index
  if order_allocations_index ~= nil and show.indexes then
    local iteration = parent:add(omi_cboe_bzxoptions_binaryorderentry_boe_v2_11_115.fields.order_allocations_index, order_allocations_index)
    iteration:set_generated()
  end

  -- Side: Alphanumeric
  index, side = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.side.dissect(buffer, index, packet, parent)

  -- Alloc Qty: Binary
  index, alloc_qty = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.alloc_qty.dissect(buffer, index, packet, parent)

  -- Cl Ord Id: Text
  index, cl_ord_id = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.cl_ord_id.dissect(buffer, index, packet, parent)

  -- Capacity: Alpha
  index, capacity = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.capacity.dissect(buffer, index, packet, parent)

  -- Open Close: Alphanumeric
  index, open_close = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.open_close.dissect(buffer, index, packet, parent)

  -- Give Up Firm Id: Alpha
  index, give_up_firm_id = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.give_up_firm_id.dissect(buffer, index, packet, parent)

  -- Runtime optional field: Account
  local account = nil

  local account_exists = number_of_new_order_cross_bitfields >= 2 and bit.rshift(bit.band(new_order_cross_bitfield_2, 0x08), 3) > 0

  if account_exists then
    index, account = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.account.dissect(buffer, index, packet, parent)
  end

  -- Runtime optional field: Cmta Number
  local cmta_number = nil

  local cmta_number_exists = number_of_new_order_cross_bitfields >= 2 and bit.rshift(bit.band(new_order_cross_bitfield_2, 0x10), 4) > 0

  if cmta_number_exists then
    index, cmta_number = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.cmta_number.dissect(buffer, index, packet, parent)
  end

  -- Runtime optional field: Clearing Account
  local clearing_account = nil

  local clearing_account_exists = number_of_new_order_cross_bitfields >= 2 and bit.rshift(bit.band(new_order_cross_bitfield_2, 0x20), 5) > 0

  if clearing_account_exists then
    index, clearing_account = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.clearing_account.dissect(buffer, index, packet, parent)
  end

  -- Runtime optional field: Clearing Optional Data
  local clearing_optional_data = nil

  local clearing_optional_data_exists = number_of_new_order_cross_bitfields >= 2 and bit.rshift(bit.band(new_order_cross_bitfield_2, 0x80), 7) > 0

  if clearing_optional_data_exists then
    index, clearing_optional_data = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.clearing_optional_data.dissect(buffer, index, packet, parent)
  end

  -- Runtime optional field: Frequent Trader Id
  local frequent_trader_id = nil

  local frequent_trader_id_exists = number_of_new_order_cross_bitfields >= 4 and bit.rshift(bit.band(new_order_cross_bitfield_4, 0x04), 2) > 0

  if frequent_trader_id_exists then
    index, frequent_trader_id = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.frequent_trader_id.dissect(buffer, index, packet, parent)
  end

  return index
end

-- Dissect: Order Allocations
cboe_bzxoptions_binaryorderentry_boe_v2_11_115.order_allocations.dissect = function(buffer, offset, packet, parent, order_allocations_index, number_of_new_order_cross_bitfields, new_order_cross_bitfield_2, new_order_cross_bitfield_4)
  if show.repeating_groups then
    -- Optionally add element to protocol tree
    parent = parent:add(omi_cboe_bzxoptions_binaryorderentry_boe_v2_11_115.fields.order_allocations, buffer(offset, 0))
    local index = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.order_allocations.fields(buffer, offset, packet, parent, order_allocations_index, number_of_new_order_cross_bitfields, new_order_cross_bitfield_2, new_order_cross_bitfield_4)
    local length = index - offset
    parent:set_len(length)
    local display = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.order_allocations.display(packet, parent, length)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    return cboe_bzxoptions_binaryorderentry_boe_v2_11_115.order_allocations.fields(buffer, offset, packet, parent, order_allocations_index, number_of_new_order_cross_bitfields, new_order_cross_bitfield_2, new_order_cross_bitfield_4)
  end
end

