-- Dissect: New Order Message
cboe_bzxoptions_binaryorderentry_boe_v2_11_115.new_order_message.dissect = function(buffer, offset, packet, parent, size_of_new_order_message)
  local size_of_new_order_message = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.new_order_message.size(buffer, offset)
  local index = offset + size_of_new_order_message

  -- Optionally add group/struct element to protocol tree
  if show.application_messages then
    parent = parent:add(omi_cboe_bzxoptions_binaryorderentry_boe_v2_11_115.fields.new_order_message, buffer(offset, 0))
    local current = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.new_order_message.fields(buffer, offset, packet, parent, size_of_new_order_message)
    parent:set_len(size_of_new_order_message)
    local display = cboe_bzxoptions_binaryorderentry_boe_v2_11_115.new_order_message.display(buffer, packet, parent)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    cboe_bzxoptions_binaryorderentry_boe_v2_11_115.new_order_message.fields(buffer, offset, packet, parent, size_of_new_order_message)

    return index
  end
end

