-- Dissector for Cboe BzxOptions BinaryOrderEntry Boe 2.11.115
function omi_cboe_bzxoptions_binaryorderentry_boe_v2_11_115.dissector(buffer, packet, parent)
  -- Set protocol name
  packet.cols.protocol = omi_cboe_bzxoptions_binaryorderentry_boe_v2_11_115.name

  local length = buffer:len()
  local index = 0

  -- Dissect each message the segment carries
  while index < length do
    local remaining = length - index

    -- The message length lives in the header: wait for the header before reading it
    if remaining < cboe_bzxoptions_binaryorderentry_boe_v2_11_115.message_header.size then
      packet.desegment_offset = index
      packet.desegment_len = DESEGMENT_ONE_MORE_SEGMENT
      return length
