    local size = buffer(index + 2, 2):le_uint() + 2
    -- A message split across segments: ask TCP for exactly the bytes still missing
    if remaining < size then
      packet.desegment_offset = index
      packet.desegment_len = size - remaining
      return length
    end

    local protocol = parent:add(omi_cboe_bzxoptions_binaryorderentry_boe_v2_11_115, buffer(index, size), omi_cboe_bzxoptions_binaryorderentry_boe_v2_11_115.description, "("..size.." Bytes)")
    cboe_bzxoptions_binaryorderentry_boe_v2_11_115.packet.dissect(buffer(index, size):tvb(), packet, protocol)
    protocol:set_len(size)
    index = index + size
  end

  return index
end


